class Gradebook:
    def __init__(self) -> None:
        # Store assignments: {name: {"weight": float, "kind": str}}
        self.assignments = {}
        # Store grades: {student: {assignment: grade}}
        self.grades = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        if kind not in ["homework", "quiz"]:
            raise ValueError(f"kind must be 'homework' or 'quiz', got '{kind}'")
        self.assignments[name] = {"weight": weight, "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        """Record a grade for a student on an assignment."""
        if grade < 2.0 or grade > 5.0:
            raise ValueError(f"Grade {grade} is outside the valid range [2.0, 5.0]")

        if student not in self.grades:
            self.grades[student] = {}

        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        """Calculate weighted average for a student, dropping lowest quiz grade if multiple quizzes exist."""
        if student not in self.grades:
            # If student has no grades at all, use default grade 2.0 for all assignments
            if not self.assignments:
                return 2.0
            total_weight = 0.0
            weighted_sum = 0.0
            for assignment_name, assignment_info in self.assignments.items():
                weight = assignment_info["weight"]
                total_weight += weight
                weighted_sum += 2.0 * weight
            if total_weight == 0.0:
                return 2.0
            return round(weighted_sum / total_weight, 2)

        # Get all assignments and their grades
        student_grades = self.grades[student]

        # Separate homework and quiz assignments
        homework_assignments = []
        quiz_assignments = []

        for assignment_name, assignment_info in self.assignments.items():
            if assignment_info["kind"] == "homework":
                homework_assignments.append((assignment_name, assignment_info))
            else:  # quiz
                quiz_assignments.append((assignment_name, assignment_info))

        # Calculate weighted sum and total weight
        weighted_sum = 0.0
        total_weight = 0.0

        # Process homework assignments
        for assignment_name, assignment_info in homework_assignments:
            grade = student_grades.get(assignment_name, 2.0)
            weight = assignment_info["weight"]
            weighted_sum += grade * weight
            total_weight += weight

        # Process quiz assignments
        # Collect all quiz grades that exist, plus default 2.0 for missing ones
        quiz_grades = []
        for assignment_name, assignment_info in quiz_assignments:
            grade = student_grades.get(assignment_name, 2.0)
            quiz_grades.append((grade, assignment_info["weight"], assignment_name))

        # If there's more than one quiz, drop the lowest grade
        if len(quiz_grades) > 1:
            # Sort by grade (ascending) to find the lowest
            quiz_grades.sort(key=lambda x: x[0])
            # Drop the lowest grade (first in sorted list)
            quiz_grades = quiz_grades[1:]

        # Add remaining quiz grades to weighted sum
        for grade, weight, _ in quiz_grades:
            weighted_sum += grade * weight
            total_weight += weight

        # Handle edge case where total_weight is 0
        if total_weight == 0.0:
            return 2.0

        # Calculate and round to two decimal places
        result = weighted_sum / total_weight
        return round(result, 2)
